def transform(grid):
    if not grid: return grid
    rows = len(grid)
    if rows == 0: return grid
    cols = len(grid[0])

    # Identify background color (most frequent)
    bg_counts = {}
    for r in range(rows):
        for c in range(cols):
            val = grid[r][c]
            bg_counts[val] = bg_counts.get(val, 0) + 1

    bg = max(bg_counts, key=bg_counts.get)

    # Create a copy of the grid to avoid modifying the input
    result_grid = [row[:] for row in grid]

    # Process each row for special pixels
    for r in range(rows):
        # Find the first special pixel in the row (not background)
        src_val = -1
        src_idx = -1
        for c in range(cols):
            if result_grid[r][c] != bg:
                src_val = result_grid[r][c]
                src_idx = c
                break

        # If a special pixel is found, apply the filling pattern to the right
        if src_idx != -1:
            # Pattern: 5, v, 5, v ... starting from the pixel immediately to the right
            # Distance 1 (odd) -> 5
            # Distance 2 (even) -> v
            for c in range(src_idx + 1, cols):
                dist = c - src_idx
                if dist % 2 == 1:
                    result_grid[r][c] = 5
                else:
                    result_grid[r][c] = src_val

    return result_grid
